create or replace function public.touch_profile_on_career_entry() returns trigger language plpgsql security definer set search_path = '' as $$ declare owner_id uuid; begin owner_id:=coalesce(new.user_id,old.user_id); if not exists(select 1 from auth.users where id=owner_id) then return coalesce(new,old); end if; insert into public.profiles(user_id,updated_at) values(owner_id,clock_timestamp()) on conflict(user_id) do update set updated_at=clock_timestamp(); return coalesce(new,old); end $$;
